"""Actual public callback skip with native-owned pending artifact bytes."""
import argparse,json,pathlib,subprocess,tempfile
p=argparse.ArgumentParser();p.add_argument('--executable',required=True,type=pathlib.Path);p.add_argument('--sdk-directory',required=True,type=pathlib.Path);p.add_argument('--directory',required=True,type=pathlib.Path);p.add_argument('--node',required=True);a=p.parse_args();receipt=a.directory.resolve();receipt.mkdir(parents=True,exist_ok=True);out=pathlib.Path(tempfile.mkdtemp(prefix='cases-',dir=receipt));sdk=a.sdk_directory.resolve();groups=[]
common="import{defineNativeSuite}from "+json.dumps((sdk/'native.js').as_uri())+";import{strict as assert}from'node:assert';import{writeFileSync}from'node:fs';"
def run(name,body,code=0):
 root=out/name;root.mkdir();suite=root/'suite.mjs';suite.write_text(common+body);r=subprocess.run([str(a.executable),'--node',a.node,'--host-script',str(sdk/'native-runner-host.js'),'--suite',str(suite),'--report',str(root/'actual.json'),'--junit',str(root/'actual.xml'),'--html',str(root/'actual.html')],capture_output=True,timeout=15);(root/'stdout.bin').write_bytes(r.stdout);(root/'stderr.bin').write_bytes(r.stderr);assert r.returncode==code and not r.stderr,(name,r.returncode,r.stdout,r.stderr);v=json.loads((root/'actual.json').read_text());groups.append({'name':name,'actualExitCode':r.returncode,'report':str(root/'actual.json')});return root,v
root,v=run('void-pending-attachment-is-owned-cancellation-not-unhandled-rejection',"export default defineNativeSuite({tests:[{title:'actual pending file test skip',run:(_,i)=>{void i.attach('pending',{body:'actual bytes'});i.skip('actual accepted cause')}}]});");assert v['attempts'][0]['status']=='skipped' and v['attempts'][0]['expected'] and not v['attachments'] and not v['globalErrors'] and not list(root.glob('suitecut-attachments-*/*'))
root,v=run('finally-awaits-real-cancellation-and-control-identity',"export default defineNativeSuite({tests:[{title:'actual cancellation identity',run:async(_,i)=>{const file=i.attach('pending',{body:new Uint8Array([0,1,128,255])});let actual;try{i.skip('cause\\ud800\\0')}catch(error){actual=error}assert(actual instanceof Error);const canceled=await file.then(()=>assert.fail('canceled API cannot claim committed artifact'),error=>error);assert.equal(canceled,actual);assert.equal(i.expectedStatus,'skipped');assert(i.signal.aborted);}}]});");assert v['attempts'][0]['status']=='skipped' and v['attempts'][0]['skipReason']=='cause\ud800\0' and not v['attachments'] and not v['globalErrors']
