root,v=run('false-condition-preserves-real-file-commit',"export default defineNativeSuite({tests:[{title:'false is no native skip',run:async(_,i)=>{const file=i.attach('actual',{body:'real committed bytes'});i.skip(false,'not admitted');await file;assert.equal(i.expectedStatus,'passed')}}]});");assert v['attempts'][0]['status']=='passed' and len(v['attachments'])==1 and pathlib.Path(v['attachments'][0]['path']).read_bytes()==b'real committed bytes'
root,v=run('completed-reference-survives-later-pending-cancellation',"export default defineNativeSuite({tests:[{title:'preserve actual earlier commit',run:async(_,i)=>{await i.attach('complete',{body:'actual retained bytes'});void i.attach('pending',{body:'actual canceled bytes'});i.skip('later native cancellation')}}]});");assert v['attempts'][0]['status']=='skipped' and len(v['attachments'])==1 and v['attachments'][0]['name']=='complete' and pathlib.Path(v['attachments'][0]['path']).read_bytes()==b'actual retained bytes'
root,v=run('caught-prior-ordinary-API-error-does-not-poison-new-owned-cause',"export default defineNativeSuite({tests:[{title:'real caught error then skip',run:async(_,i)=>{await assert.rejects(i.attach('missing',{path:''}),/errno=2/);void i.attach('pending',{body:'actual new bytes'});i.skip('new accepted cause')}}]});");assert v['attempts'][0]['status']=='skipped' and not v['attachments'] and not v['globalErrors']
root,v=run('beforeAll-pending-attachment-skip-remains-explicitly-unsupported',"export default defineNativeSuite({hooks:{beforeAll:[{run:async(_,i)=>{const file=i.attach('actual',{body:'actual beforeAll bytes'});try{i.skip('unsupported pending all-hook')}catch{}await file}}]},tests:[{title:'unadmitted body',run:()=>assert.fail('beforeAll mutation failure must block body')}]});",1);assert v['attempts'][0]['status']=='failed' and not v['skipCauses'] and not v['runtimeSkipped'] and 'runtime skip rejected' in v['attempts'][0]['error']
root,v=run('flat-fixture-teardown-waits-real-callback-finally-and-file-terminal',"import{setTimeout as wait}from'node:timers/promises';let finallyDone=false,fileDone=false;export default defineNativeSuite({fixtures:{owned:{setup:async(_,use)=>{await use(1);assert(finallyDone&&fileDone,'fixture teardown must follow actual callback and file terminal');}}},tests:[{title:'actual flat cleanup order',fixtures:['owned'],run:async(_,i)=>{const file=i.attach('pending',{body:'actual file'});try{i.skip('actual owned cancellation')}finally{await assert.rejects(file);fileDone=true;await wait(30);finallyDone=true;}}}]});");assert v['attempts'][0]['status']=='skipped' and not v['attachments'] and not v['globalErrors']
