root,v=run('actual-raw-error-after-accepted-skip-is-not-suppressed',"export default defineNativeSuite({tests:[{title:'actual callback error after skip',expectedFailure:true,run:async(_,i)=>{const file=i.attach('pending',{body:'actual file'});try{i.skip('native cancellation')}catch{}await assert.rejects(file);throw new Error('actual unrelated author failure')}}]});",1);assert v['attempts'][0]['status']=='failed' and not v['attempts'][0]['expected'] and 'actual unrelated author failure' in v['attempts'][0]['error'] and not v['attachments']
